import{_ as t}from"./chunks/rules-trigger-de.BglIPUQ6.js";import{_ as a,o as r,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const i="/images/logic-studio/user-guide/rules-walkthrough-en.jpg",f=JSON.parse('{"title":"Rules","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/logic-studio/user-guide/rules.md","filePath":"en/projects/logic-studio/user-guide/rules.md","lastUpdated":1795179952000}'),s={name:"en/projects/logic-studio/user-guide/rules.md"};function d(h,e,l,c,g,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h1><h2 id="create-a-rule-for-a-hallway-light" tabindex="-1">Create a rule for a hallway light <a class="header-anchor" href="#create-a-rule-for-a-hallway-light" aria-label="Permalink to &quot;Create a rule for a hallway light&quot;">​</a></h2><h3 id="_1-create-the-project" tabindex="-1">1. Create the project <a class="header-anchor" href="#_1-create-the-project" aria-label="Permalink to &quot;1. Create the project&quot;">​</a></h3><p>Choose <strong>New project → Rules</strong>, name it, then open the <strong>wizard</strong>. Its four steps cover triggers, conditions, actions and review.</p><h3 id="_2-set-the-trigger" tabindex="-1">2. Set the trigger <a class="header-anchor" href="#_2-set-the-trigger" aria-label="Permalink to &quot;2. Set the trigger&quot;">​</a></h3><p>Choose <strong>State</strong>. Enter your motion sensor or first test helper as the entity. The demo uses <code>binary_sensor.bewegung</code>. Enter <code>on</code> in <strong>To</strong> and leave <strong>From</strong>, attribute and minimum duration empty. Click <strong>Next</strong>.</p><p><a href="/images/logic-studio/user-guide/rules-trigger-de.jpg"><img src="'+t+'" alt="State trigger in the Rules wizard, shown in the German interface"></a></p><h3 id="_3-skip-conditions" tabindex="-1">3. Skip conditions <a class="header-anchor" href="#_3-skip-conditions" aria-label="Permalink to &quot;3. Skip conditions&quot;">​</a></h3><p>Click <strong>Next</strong> in the conditions step. A condition is an extra check, such as limiting the rule to evenings. This example runs whenever the trigger matches.</p><h3 id="_4-add-the-action" tabindex="-1">4. Add the action <a class="header-anchor" href="#_4-add-the-action" aria-label="Permalink to &quot;4. Add the action&quot;">​</a></h3><p>Under <strong>THEN</strong>, click <strong>+ Add</strong> and leave the step type set to <strong>HA action</strong>. Set the action to <code>light.turn_on</code> and choose your test light as the target. The demo uses <code>light.flur</code>. For a second toggle helper, use <code>input_boolean.turn_on</code> instead. Leave <strong>ELSE</strong> empty and click <strong>Next</strong>.</p><h3 id="_5-review-and-open-the-yaml" tabindex="-1">5. Review and open the YAML <a class="header-anchor" href="#_5-review-and-open-the-yaml" aria-label="Permalink to &quot;5. Review and open the YAML&quot;">​</a></h3><p>Check the entity and <code>to: &quot;on&quot;</code> under <code>triggers</code>. Check the action and its target under <code>actions</code>. Apply the wizard, save the rule, then use <strong>Open as HA YAML</strong> to review and export the draft.</p><h3 id="_6-try-it-in-home-assistant" tabindex="-1">6. Try it in Home Assistant <a class="header-anchor" href="#_6-try-it-in-home-assistant" aria-label="Permalink to &quot;6. Try it in Home Assistant&quot;">​</a></h3><p>Add the reviewed automation to Home Assistant. Set the trigger entity to <code>off</code>, then to <code>on</code>. Check that the correct target turned on. The automation trace shows the trigger and action that ran.</p><p><a href="/images/logic-studio/user-guide/rules-walkthrough-en.jpg"><img src="'+i+'" alt="Rules editor with a state trigger in IF and a light action in THEN"></a></p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="wizard-and-palette" tabindex="-1">Wizard and palette <a class="header-anchor" href="#wizard-and-palette" aria-label="Permalink to &quot;Wizard and palette&quot;">​</a></h3><p>The wizard guides you through the rule. Search the palette or drag an item into the matching section.</p><h3 id="triggers" tabindex="-1">Triggers <a class="header-anchor" href="#triggers" aria-label="Permalink to &quot;Triggers&quot;">​</a></h3><p>Choose a state change with from/to, attribute and duration, a numeric threshold, fixed or helper time, sun with offset, MQTT, HA event or HA start. Areas and labels group the selected entities.</p><h3 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h3><p>Check a state, number, attribute, time or weekday. AND requires all checks, OR any, and NOT reverses a check.</p><h3 id="triggered-by" tabindex="-1">Triggered by <a class="header-anchor" href="#triggered-by" aria-label="Permalink to &quot;Triggered by&quot;">​</a></h3><p>Assign IDs such as <code>first</code> and <code>second</code> and use the ID as a condition to select THEN or ELSE.</p><h3 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h3><p>In Expert mode, add a native HA template whose result decides whether the condition passes.</p><h3 id="actions-and-branches" tabindex="-1">Actions and branches <a class="header-anchor" href="#actions-and-branches" aria-label="Permalink to &quot;Actions and branches&quot;">​</a></h3><p>Add actions in order. Choose a target and parameters, add a delay, wait for a state, call a script or send a notification.</p><h3 id="yaml-and-rules-json" tabindex="-1">YAML and Rules JSON <a class="header-anchor" href="#yaml-and-rules-json" aria-label="Permalink to &quot;YAML and Rules JSON&quot;">​</a></h3><p>Use YAML in HA and Rules JSON to reopen the rule in the editor.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>A threshold triggers again after the value leaves the range and re-enters.</p>',33)])])}const b=a(s,[["render",d]]);export{f as __pageData,b as default};
